import { Component } from '@angular/core';
import { CommandComponent } from './command.component';
import { DialogComponent } from './dialog.component';
import { ButtonDirective } from './button.directive';

@Component({
  selector: 'app-demo',
  imports: [CommandComponent, DialogComponent, ButtonDirective],
  template: `
    <div class="max-w-md">
        <app-command
            [items]="items"
            [placeholder]="placeholder"
            [emptyText]="emptyText"
            (selected)="pick($event)" />
        <p class="mt-4 text-sm">Selected: {{ last || 'none' }}</p>
    </div>`,
})
export class DemoComponent {
  items = [{value: 'book', label: 'Book appointment', group: 'Appointments', shortcut: 'Ctrl+B'}, {value: 'upcoming', label: 'View upcoming', group: 'Appointments'}, {value: 'cancel', label: 'Cancel appointment', group: 'Appointments', disabled: true}, {value: 'doctors', label: 'Find a doctor', group: 'Directory', shortcut: 'Ctrl+D'}, {value: 'profile', label: 'Profile', group: 'Settings'}, {value: 'settings', label: 'Settings', group: 'Settings', shortcut: 'Ctrl+,'}];
  placeholder = 'Type a command or search...';
  emptyText = 'No results found.';
  selected(event: unknown) {}
}

overlays-command--in-dialog.snippet:
import { Component } from '@angular/core';
import { CommandComponent } from './command.component';
import { DialogComponent } from './dialog.component';
import { ButtonDirective } from './button.directive';

@Component({
  selector: 'app-demo',
  imports: [CommandComponent, DialogComponent, ButtonDirective],
  template: `
    <button
        appButton
        variant="outline"
        (click)="open = true">
        Open command palette
    </button>
    <app-dialog heading="Command palette" [(open)]="open">
        <app-command
            [items]="items"
            [placeholder]="placeholder"
            [emptyText]="emptyText"
            (selected)="open = false" />
    </app-dialog>`,
})
export class DemoComponent {
  items = [{value: 'book', label: 'Book appointment', group: 'Appointments', shortcut: 'Ctrl+B'}, {value: 'upcoming', label: 'View upcoming', group: 'Appointments'}, {value: 'cancel', label: 'Cancel appointment', group: 'Appointments', disabled: true}, {value: 'doctors', label: 'Find a doctor', group: 'Directory', shortcut: 'Ctrl+D'}, {value: 'profile', label: 'Profile', group: 'Settings'}, {value: 'settings', label: 'Settings', group: 'Settings', shortcut: 'Ctrl+,'}];
  placeholder = 'Type a command or search...';
  emptyText = 'No results found.';
  selected(event: unknown) {}
}
